/**
 * Token-Cost Tracker — tool-local actions.
 *
 * Category: AI / LLM Product Management (squad S12b)
 * Tool:     Roll up per-feature / per-model token spend, with a pure
 *           month-end cost projection for budget reasoning.
 *
 * Agent surface: tool.token_cost_tracker.*
 * Backing CRUD : workspace.token_spend.* (auto-generated by
 *                defineCrudActions in src/lib/actions/workspace/index.ts).
 *
 * ─── CRUD-BACKED tool pattern (see mood-tracker.ts for the analog) ──────
 * Spend entries are a record-keeping entity — generic create / list /
 * update / delete already exist via workspace.token_spend.*. This file
 * adds the domain verbs:
 *
 *   1. list_state                — totals + byFeature/byModel rollups in one
 *                                  round-trip ("what are we spending and
 *                                  where?").
 *   2. compute_monthly_projection — pure: linear month-end forecast from
 *                                  spend-so-far + days-elapsed, optionally
 *                                  vs a budget. No persistence — lets the
 *                                  agent answer "are we on track to blow the
 *                                  budget?" against trial numbers.
 *   3. record_spend              — log a spend entry (date defaults to
 *                                  today). Additive, no confirmation.
 *
 * Entity kind "workspace:tokenSpend" (camelCase via kindFromToolId of
 * "workspace.token_spend") matches the browser sync engine, so MCP writes
 * round-trip into the UI.
 */

import { z } from "zod";
import { registry } from "../registry";
import { useWorkspaceStore } from "@/lib/stores/workspace-store";
import { serverListEntities, serverUpsertEntity } from "../server-store";
import type { TokenSpend } from "@/lib/stores/workspace-types";

const KIND_TOKEN_SPEND = "workspace:tokenSpend";

const ws = () => useWorkspaceStore.getState();

/** Round to 4 decimals — sub-cent granularity matters for per-1k-token
 *  costs, and it strips binary-float drift (0.1 + 0.2 → 0.3). */
const round4 = (n: number) => Math.round(n * 10000) / 10000;

/** Group spend by a key (feature or model), summing cost + tokens. Returned
 *  as an array sorted by cost desc so the biggest line items lead. */
function rollup(items: TokenSpend[], key: "feature" | "model") {
  const acc = new Map<
    string,
    { costUsd: number; inputTokens: number; outputTokens: number; entries: number }
  >();
  for (const it of items) {
    const k = it[key];
    const cur = acc.get(k) ?? { costUsd: 0, inputTokens: 0, outputTokens: 0, entries: 0 };
    cur.costUsd += it.costUsd;
    cur.inputTokens += it.inputTokens;
    cur.outputTokens += it.outputTokens;
    cur.entries += 1;
    acc.set(k, cur);
  }
  return Array.from(acc.entries())
    .map(([name, v]) => ({ name, ...v, costUsd: round4(v.costUsd) }))
    .sort((a, b) => b.costUsd - a.costUsd);
}

function summarize(items: TokenSpend[]) {
  let totalCostUsd = 0;
  let totalInputTokens = 0;
  let totalOutputTokens = 0;
  for (const it of items) {
    totalCostUsd += it.costUsd;
    totalInputTokens += it.inputTokens;
    totalOutputTokens += it.outputTokens;
  }
  return {
    totalEntries: items.length,
    totalCostUsd: round4(totalCostUsd),
    totalInputTokens,
    totalOutputTokens,
    byFeature: rollup(items, "feature"),
    byModel: rollup(items, "model"),
  };
}

// ──────── tool.token_cost_tracker.list_state ────────
registry.register({
  id: "tool.token_cost_tracker.list_state",
  toolId: "tool.token_cost_tracker",
  name: "list_state",
  category: "read",
  description:
    "Summarise token spend. Returns {totalEntries, totalCostUsd, totalInputTokens, totalOutputTokens, byFeature: {name, costUsd, inputTokens, outputTokens, entries}[], byModel: same[]}. byFeature/byModel are sorted by cost descending.",
  paramsSchema: z.object({}),
  handler: async () => summarize(ws().tokenSpend ?? []),
  mcpHandler: async (_params, ctx) => {
    const items = await serverListEntities<TokenSpend>(ctx.userId, KIND_TOKEN_SPEND);
    return summarize(items);
  },
});

// ──────── tool.token_cost_tracker.compute_monthly_projection ────────
// Pure: extrapolate a linear month-end cost from spend-so-far. dailyRate =
// spentUsd / daysElapsed; projection = dailyRate * daysInMonth. Optionally
// compares against a budget. No side effects → the agent can run "what if
// we're 10 days in at $40?" scenarios without touching the workspace.
registry.register({
  id: "tool.token_cost_tracker.compute_monthly_projection",
  toolId: "tool.token_cost_tracker",
  name: "compute_monthly_projection",
  category: "read",
  description:
    "Linear month-end cost projection from spend-so-far. Given spentUsd over daysElapsed, returns {dailyRateUsd, projectedMonthEndUsd}. When monthlyBudgetUsd is supplied, also returns {pctOfBudget (0..1+), overBudget}. daysInMonth defaults to 30. Pure — no persistence.",
  paramsSchema: z.object({
    spentUsd: z.number().min(0),
    daysElapsed: z.number().positive().describe("Days of spend so far in the period (> 0)."),
    daysInMonth: z.number().positive().optional().describe("Defaults to 30 when omitted."),
    monthlyBudgetUsd: z.number().positive().optional(),
  }),
  handler: async (params) => {
    // Default applied here (not via zod .default) so the handler never NaNs
    // when called with raw params — mirrors mood-tracker's date default.
    const daysInMonth = params.daysInMonth ?? 30;
    const dailyRateUsd = params.spentUsd / params.daysElapsed;
    const projectedMonthEndUsd = round4(dailyRateUsd * daysInMonth);
    const base = { dailyRateUsd: round4(dailyRateUsd), projectedMonthEndUsd };
    if (params.monthlyBudgetUsd === undefined) return base;
    return {
      ...base,
      pctOfBudget: round4(projectedMonthEndUsd / params.monthlyBudgetUsd),
      overBudget: projectedMonthEndUsd > params.monthlyBudgetUsd,
    };
  },
  // No mcpHandler — pure compute runs identically on server and client.
});

// ──────── tool.token_cost_tracker.record_spend ────────
registry.register({
  id: "tool.token_cost_tracker.record_spend",
  toolId: "tool.token_cost_tracker",
  name: "record_spend",
  category: "write",
  requiresConfirmation: false,
  description:
    "Record a token-spend entry for a feature + model. date defaults to today (YYYY-MM-DD). Returns {added: true, id}.",
  paramsSchema: z.object({
    feature: z.string().min(1).max(200),
    model: z.string().min(1).max(200),
    inputTokens: z.number().int().min(0),
    outputTokens: z.number().int().min(0),
    costUsd: z.number().min(0),
    date: z.string().optional().describe("YYYY-MM-DD; defaults to today."),
  }),
  handler: async (params) => {
    const entry: TokenSpend = {
      id: crypto.randomUUID(),
      feature: params.feature,
      model: params.model,
      inputTokens: params.inputTokens,
      outputTokens: params.outputTokens,
      costUsd: params.costUsd,
      date: params.date ?? new Date().toISOString().slice(0, 10),
    };
    ws().upsertTokenSpend(entry);
    return { added: true, id: entry.id };
  },
  mcpHandler: async (params, ctx) => {
    const entry: TokenSpend = {
      id: crypto.randomUUID(),
      feature: params.feature,
      model: params.model,
      inputTokens: params.inputTokens,
      outputTokens: params.outputTokens,
      costUsd: params.costUsd,
      date: params.date ?? new Date().toISOString().slice(0, 10),
    };
    await serverUpsertEntity<TokenSpend>(ctx.userId, KIND_TOKEN_SPEND, entry);
    return { added: true, id: entry.id };
  },
});
